                g[r][c] = color
                rr = r + step
                while 0 <= rr < h:
                    g[rr][c] = color
                    rr += step
                # Discard the dead tail before the last perpendicular junction.
                junction = None
                rr = r - step
                while 0 <= rr < h and grid[rr][c] == color:
                    if any(0 <= cc < w and grid[rr][cc] == color for cc in (c-1, c+1)):
                        junction = rr
                    rr -= step
                if junction is not None:
                    rr = junction - step
                    while 0 <= rr < h and g[rr][c] == color:
                        g[rr][c] = 0
                        rr -= step

