            colors = [grid[r][c] for c in range(a+1, b) if grid[r][c] not in (0, 2, 4)]
            if colors:
                color = max(set(colors), key=colors.count)
                for c in range(a, b+1):
                    g[r][c] = color
    for c in range(w):
        ends = [r for r in range(h) if grid[r][c] == 2]
        if len(ends) == 2:
            a, b = ends
            colors = [grid[r][c] for r in range(a+1, b) if grid[r][c] not in (0, 2, 4)]
            if colors:
                color = max(set(colors), key=colors.count)
                for r in range(a, b+1):
                    g[r][c] = color

    # Repair one-cell breaks. Horizontal strokes take precedence at crossings.
    for r in range(h):
        for c in range(1, w-1):
            if grid[r][c-1] == grid[r][c+1] and grid[r][c-1] not in (0, 2, 4):
