                if all(grid[r][cc] in (0, 3, 7) for cc in range(w)):
                    for cc in range(w):
                        if grid[r][cc] == 3 and (cc < c or grid[r][cc+1] == 0):
                            g[r][cc] = 0
                    g[r][c] = 7
    return g
